using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, quantities, shapes, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language arts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilizations." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her Ph.D. from MIT and has published extensively on programming pedagogy.", Schedule = "Mon/Wed/Fri 9:00–9:50 AM", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Instructor = "Dr. James Park", InstructorBio = "Dr. Park is a renowned algorithms researcher with contributions to graph theory. He holds a Ph.D. from Stanford University.", Schedule = "Tue/Thu 10:30 AM–12:00 PM", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Introduction to database design, SQL, normalization, transaction management, and modern NoSQL systems.", Credits = 3, Instructor = "Prof. Maria Garcia", InstructorBio = "Prof. Garcia spent a decade in industry at major tech companies before joining academia. She specializes in distributed database systems.", Schedule = "Mon/Wed 2:00–3:20 PM", IsFeatured = false },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Foundations of machine learning including supervised and unsupervised learning, neural networks, and practical applications.", Credits = 4, Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her Ph.D. from MIT and has published extensively on programming pedagogy.", Schedule = "Tue/Thu 1:00–2:30 PM", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Instructor = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning mathematics educator with over 20 years of teaching experience. He has authored several popular calculus textbooks.", Schedule = "Mon/Wed/Fri 10:00–10:50 AM", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications.", Credits = 3, Instructor = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research focuses on applied linear algebra and numerical methods. She consults for aerospace companies on computational problems.", Schedule = "Tue/Thu 9:00–10:20 AM", IsFeatured = false },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Instructor = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning mathematics educator with over 20 years of teaching experience. He has authored several popular calculus textbooks.", Schedule = "Mon/Wed 11:00 AM–12:20 PM", IsFeatured = false },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "101", Title = "English Composition", Description = "Development of writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Instructor = "Prof. Daniel Brooks", InstructorBio = "Prof. Brooks is a published author and writing coach. He holds an MFA in Creative Writing from the Iowa Writers' Workshop.", Schedule = "Mon/Wed/Fri 11:00–11:50 AM", IsFeatured = false },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present day.", Credits = 3, Instructor = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison specializes in 20th-century American fiction. She has published three books on the Harlem Renaissance.", Schedule = "Tue/Thu 2:00–3:20 PM", IsFeatured = true },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Instructor = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an experimental physicist whose research includes particle physics at CERN. He is passionate about making physics accessible to all students.", Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", IsFeatured = false },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Instructor = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's research focuses on photonics and optical communications. She holds multiple patents in fiber optic technology.", Schedule = "Tue/Thu 10:00–11:30 AM", IsFeatured = false },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period.", Credits = 3, Instructor = "Dr. Patricia Owens", InstructorBio = "Dr. Owens is an archaeologist and historian specializing in ancient Mediterranean civilizations. She has led excavations in Greece and Turkey.", Schedule = "Mon/Wed 3:00–4:20 PM", IsFeatured = false },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "205", Title = "Modern World History", Description = "Global developments from 1500 to the present including colonialism, industrialization, world wars, and globalization.", Credits = 3, Instructor = "Dr. Kevin O'Brien", InstructorBio = "Dr. O'Brien is an expert in modern European and colonial history. He has been a visiting scholar at Oxford and the Sorbonne.", Schedule = "Tue/Thu 3:30–4:50 PM", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Department? GetDepartmentByCode(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? query, string? departmentCode)
    {
        var results = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            results = results.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourse(request.CourseId) is not null;
    }
}

