@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@inject CatalogService Catalog

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseTitle</strong> has been received.</p>
        <a href="enroll" class="btn btn-primary mt-2">Submit Another Request</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <form method="post" class="col-md-8">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName" value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId" value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">-- Select a course --</option>
                @foreach (var course in Catalog.GetAllCourses())
                {
                    <option value="@course.Id" selected="@(course.Id == Model.CourseId)">@course.FullCode &ndash; @course.Title (@course.Credits cr)</option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContext.Request.Method) && Model.CourseId > 0)
        {
            var course = Catalog.GetCourse(Model.CourseId);
            if (course is not null && !string.IsNullOrWhiteSpace(Model.StudentName) && !string.IsNullOrWhiteSpace(Model.StudentId))
            {
                selectedCourseTitle = $"{course.FullCode} – {course.Title}";
                Catalog.SubmitEnrollmentRequest(Model);
                submitted = true;
            }
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

